import{_ as o,l,o as e,c as i,v as r,p as s,x as t,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"最近公共祖先","description":"","frontmatter":{"title":"最近公共祖先","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/lca.md","filePath":"cs/lca.md","lastUpdated":1789023840000}'),h={name:"cs/lca.md"};function A(m,a,B,u,_,C){const n=l("Mermaid");return e(),i("div",null,[a[1]||(a[1]=r('<h1 id="最近公共祖先" tabindex="-1">最近公共祖先 <a class="header-anchor" href="#最近公共祖先" aria-label="Permalink to &quot;最近公共祖先&quot;">​</a></h1><div class="epigraph"><p>树上两点的最近公共祖先是同时盖住二者的最深顶点；离线并查集或在线倍增、欧拉序加 RMQ，都能答。</p><footer>—— 据 Tarjan, Applications of Path Compression on Balanced Trees, 1979；Harel and Tarjan, Fast Algorithms for Finding Nearest Common Ancestors, 1984；Bender and Farach-Colton, The LCA Problem Revisited, 2000 整理</footer></div><p>上一课<a href="/cs/hamiltonian-tsp-exact">哈密顿与 TSP 精确解</a>在一般图上指数。本课把图收成<strong>树</strong>（或有根树）：两点之间唯一路径，询问最近公共祖先（LCA）。不重做子集 DP。缺口是查询结构——离线一次扫完，或预处理后在线。后课倍增把同一技巧用到路径聚合与树上差分。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>有根树，\\(lca(u,v)\\) 为 \\(u\\)、\\(v\\) 的公共祖先中深度最大者。路径 \\(u\\)–\\(v\\) 就是 \\(u\\) 到 \\(lca\\) 再下到 \\(v\\)。朴素双指针上跳 \\(O(n)\\) 每次。缺口是更快：离线 \\(m\\) 次询问，或预处理后 \\(O(1)\\)/\\(O(\\log n)\\)。</p><p>Tarjan 离线：DFS 时用并查集维护「已处理子树的代表」；回溯时把询问另一端已访的点与当前点求 LCA。一次 DFS + 几乎 \\(O(n+m)\\)。在线：预处理深度与父，或欧拉序（进出把树摊成序列，LCA 变成序列上的 RMQ）。</p><h3 id="rmq-不是另一道题" tabindex="-1">RMQ 不是另一道题 <a class="header-anchor" href="#rmq-不是另一道题" aria-label="Permalink to &quot;RMQ 不是另一道题&quot;">​</a></h3><p>欧拉序上相邻深度差 \\(1\\)，\\(\\pm 1\\) RMQ 可 \\(O(n)\\) 预处理、\\(O(1)\\) 查询（Bender–Farach-Colton）。一般 RMQ 稀疏表 \\(O(n\\log n)\\)–\\(O(1)\\)。本课认「LCA \\(\\leftrightarrow\\) RMQ」，不把稀疏表写成另一课程。</p><p><span class="marginnote">Tarjan 1979 离线并查集。Harel–Tarjan 1984 讨论在线线性预处理。Bender–Farach-Colton 2000 把 \\(\\pm 1\\) RMQ 写清楚。后课树上倍增是同一父指针的对数张表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>小 \\(n\\) 可倍增：<code>fa[k][u]</code> 为 \\(u\\) 的 \\(2^k\\) 祖先，预处理 \\(O(n\\log n)\\)，查询先对齐深度再一起跳，\\(O(\\log n)\\)。离线用并查集。需要常数查询再用欧拉序 RMQ。</p>',11)),(e(),s(p,null,{default:t(()=>[c(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E6%9C%89%E6%A0%B9%E6%A0%91%22%5D%20--%3E%20OFF%5B%22%E7%A6%BB%E7%BA%BF%EF%BC%9ADFS%20%2B%20%E5%B9%B6%E6%9F%A5%E9%9B%86%22%5D%0A%20%20T%20--%3E%20BIN%5B%22%E5%9C%A8%E7%BA%BF%EF%BC%9A%E5%80%8D%E5%A2%9E%20fa%5Bk%5D%5Bu%5D%22%5D%0A%20%20T%20--%3E%20RMQ%5B%22%E6%AC%A7%E6%8B%89%E5%BA%8F%20%2B%20RMQ%22%5D%0A%20%20OFF%20--%3E%20LCA%5B%22lca(u%2Cv)%22%5D%0A%20%20BIN%20--%3E%20LCA%0A%20%20RMQ%20--%3E%20LCA%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>森林：先找根；不同树无 LCA，或虚根。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>括号序/欧拉序：第一次访问时刻之间的点，深度最小者即 LCA（更精确：欧拉序区间内深度最小的顶点）。倍增：深度差的二进制分解是在链上跳，与<a href="/cs/fast-exponentiation">二进制快速幂</a>同一「倍增」念头，后课才把矩阵幂展开；本课只跳父指针。</p><p>不要在有环图上定义 LCA：最近公共祖先依赖树（或 DAG 上要另定义，本课不写）。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写重链剖分（下一课的下一课）、不写点分治。动态加点、换根在线是另一模型。后课默认：树上两点路径经过 LCA；倍增表是标准预处理。下一课把倍增接到路径和与树上差分。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LCA 是两点路径的最高点；树上路径唯一。</li><li>离线并查集；在线倍增或欧拉序 RMQ。</li><li>一般图的「祖先」没有这一定义。</li><li>出处：Tarjan, 1979；Harel and Tarjan, 1984；Bender and Farach-Colton, 2000。</li></ul>',8))])}const E=o(h,[["render",A]]);export{T as __pageData,E as default};
